-- ─── 2. NPCs novos (Morbius.md) ───
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Morbius', 'Dr. Michael Morbius', 'midnight-sons', 'alto', '{"iniciativa":22,"stats":{"destreza":13,"força":7,"corpo":8,"inteligência":9,"vontade":8,"mente":7,"influência":6,"aura":7,"espírito":4},"temas":[{"nome":"Vampiro Vivo","poder":[{"texto":"Voo Sobre-humano","grau":4},{"texto":"Garras e Presas Retráteis","grau":4},{"texto":"Fator de Cura Acelerado","grau":4},{"texto":"Hipnose e Controle Mental","grau":4},{"texto":"Mordida Transforma Vítimas em Vampiros","grau":5}],"fraqueza":[]},{"nome":"Gênio Bioquímico","poder":[{"texto":"Gênio em Bioquímica e Hematologia","grau":5},{"texto":"Soro de Sangue Irradiado (transformação temporária em humano)","grau":3},{"texto":"Identidade Falsa (Morgan Michaels)","grau":3}],"fraqueza":[]},{"nome":"Herança Lilin","poder":[],"fraqueza":[{"texto":"Aversão à Luz Solar","grau":3},{"texto":"Sede Incontrolável por Sangue","grau":4},{"texto":"Ausência de Alma (confirmada por Doutor Estranho)","grau":5},{"texto":"Sangue Lilin Corruptor (pode perder o controle)","grau":3}]}],"tags":[{"texto":"Voo Sobre-humano","grau":4},{"texto":"Garras e Presas Retráteis","grau":4},{"texto":"Fator de Cura Acelerado","grau":4},{"texto":"Hipnose e Controle Mental","grau":4},{"texto":"Gênio em Bioquímica e Hematologia","grau":5},{"texto":"Mordida Transforma Vítimas em Vampiros","grau":5},{"texto":"Soro de Sangue Irradiado (transformação temporária em humano)","grau":3},{"texto":"Identidade Falsa (Morgan Michaels)","grau":3},{"texto":"Aversão à Luz Solar","grau":3},{"texto":"Sede Incontrolável por Sangue","grau":4},{"texto":"Ausência de Alma (confirmada por Doutor Estranho)","grau":5},{"texto":"Sangue Lilin Corruptor (pode perder o controle)","grau":3}],"descricao":"Dr. Michael Morbius, o Vampiro Vivo – uma tragédia científica forjada na tentativa de curar sua própria doença sanguínea. Nobel em bioquímica, sua experiência com DNA de morcego-vampiro o transformou em um pseudo-vampiro com força (STR 8), resistência (BOD 8) e voo. Sua mente genial (INT 9) ainda busca uma cura definitiva, enquanto seu corpo clama por sangue – preferencialmente dos culpados, como jurou após o Julgamento do Motoqueiro Fantasma. Sem alma (ESP 4), mas com um código moral tortuoso, Morbius transita entre herói e monstro, já tendo liderado os Midnight Sons contra Lilith e enganado o próprio Doutor Estranho. Sua maior fraqueza é a constante batalha interna contra o instinto predatório e a essência demoníaca de Lilin que carrega."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Morbius' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Vic Slaughter', 'Vic Slaughter (Cria Vampírica)', 'midnight-sons', 'medio', '{"iniciativa":20,"stats":{"destreza":7,"força":7,"corpo":7,"inteligência":5,"vontade":6,"mente":5,"influência":4,"aura":5,"espírito":5},"temas":[{"nome":"Cria Vampírica","poder":[{"texto":"Força e Velocidade Vampíricas Aprimoradas","grau":4},{"texto":"Fator de Cura Moderado","grau":3},{"texto":"Garras e Presas","grau":3},{"texto":"Distorção Corporal (pode estender membros)","grau":3}],"fraqueza":[]},{"nome":"Mercenário Preso","poder":[{"texto":"Lealdade Forçada a Morbius","grau":3},{"texto":"Ex-líder dos Hardcases","grau":3}],"fraqueza":[{"texto":"Sede de Sangue (menos controlada que Morbius)","grau":4},{"texto":"Vulnerável a Luz Solar e Símbolos Sagrados","grau":3},{"texto":"Sem Habilidades Científicas","grau":2}]}],"tags":[{"texto":"Força e Velocidade Vampíricas Aprimoradas","grau":4},{"texto":"Fator de Cura Moderado","grau":3},{"texto":"Garras e Presas","grau":3},{"texto":"Distorção Corporal (pode estender membros)","grau":3},{"texto":"Lealdade Forçada a Morbius","grau":3},{"texto":"Ex-líder dos Hardcases","grau":3},{"texto":"Sede de Sangue (menos controlada que Morbius)","grau":4},{"texto":"Vulnerável a Luz Solar e Símbolos Sagrados","grau":3},{"texto":"Sem Habilidades Científicas","grau":2}],"descricao":"Vic Slaughter era um mercenário implacável, líder dos Hardcases, até que uma tentativa de matar Morbius terminou com ele sendo enterrado vivo – e depois mordido, transformando-se na primeira cria vampírica conhecida do Dr. Morbius. Sua força (STR 7) e agilidade (DEX 7) são significativamente aumentadas, e ele herdou a capacidade de distorcer o próprio corpo. Ao contrário de seu criador, Vic não tem qualquer escrúpulo científico ou moral; sua sede é brutal e sua lealdade a Morbius é mais um reflexo do vínculo de sangue do que de respeito. Já enfrentou os Nightstalkers e serviu como capanga, mas frequentemente age por conta própria quando a fome aperta. Sua falta de intelecto (INT 5) e controle emocional o tornam mais previsível, mas também mais perigoso em confrontos diretos."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Vic Slaughter' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Estrela Polar', 'Jean‑Paul Beaubier', 'x-men', 'alto', '{"iniciativa":30,"stats":{"destreza":10,"força":5,"corpo":6,"inteligência":7,"vontade":8,"mente":7,"influência":7,"aura":8,"espírito":8},"temas":[{"nome":"Velocista Supersónico","poder":[{"texto":"Velocidade Supersónica","grau":5},{"texto":"Voo e Reflexos Sobre‑Humanos","grau":4}],"fraqueza":[]},{"nome":"Herança da Alfa Flight","poder":[{"texto":"Gêmeo de Aurora","grau":3},{"texto":"Ex‑membro da Alfa Flight","grau":3}],"fraqueza":[{"texto":"Orgulho Francês‑Canadense","grau":2}]}],"tags":[{"texto":"Velocidade Supersónica","grau":5},{"texto":"Voo e Reflexos Sobre‑Humanos","grau":4},{"texto":"Gêmeo de Aurora","grau":3},{"texto":"Ex‑membro da Alfa Flight","grau":3},{"texto":"Orgulho Francês‑Canadense","grau":2}],"descricao":"Jean‑Paul Beaubier, o Estrela Polar, é um dos mutantes mais rápidos do mundo – capaz de alcançar velocidades supersónicas em fracções de segundo. Antigo membro da Alfa Flight, trouxe a sua disciplina e orgulho para os X‑Men, onde co‑orienta o Esquadrão Alfa ao lado de Karma. A sua personalidade directa e por vezes arrogante esconde uma lealdade inabalável aos seus alunos."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Estrela Polar' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Boggart', 'Boggart', 'x-men', 'medio', '{"iniciativa":20,"stats":{"destreza":6,"força":4,"corpo":5,"inteligência":6,"vontade":7,"mente":7,"influência":5,"aura":8,"espírito":6},"temas":[{"nome":"Pesadelo Vivo","poder":[{"texto":"Metamorfose Aterrorizante","grau":4},{"texto":"Formas Baseadas no Medo do Alvo","grau":4}],"fraqueza":[]},{"nome":"Coração Leal","poder":[{"texto":"Humor Sombrio e Brincalhão","grau":3},{"texto":"Lealdade Feroz aos Amigos","grau":3}],"fraqueza":[{"texto":"Aspecto Assustador Permanente","grau":2}]}],"tags":[{"texto":"Metamorfose Aterrorizante","grau":4},{"texto":"Formas Baseadas no Medo do Alvo","grau":4},{"texto":"Humor Sombrio e Brincalhão","grau":3},{"texto":"Lealdade Feroz aos Amigos","grau":3},{"texto":"Aspecto Assustador Permanente","grau":2}],"descricao":"Boggart é um ser místico cuja aparência é naturalmente sinistra, mas que se revela um companheiro leal e bem‑humorado. O seu poder de assumir formas aterrorizantes não é usado para magoar, mas para assustar com um toque de comédia negra – o que poucos apreciam. Vive num constante conflito entre o que parece e o que é."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Boggart' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Náiade', 'Naiad', 'x-men', 'medio', '{"iniciativa":22,"stats":{"destreza":7,"força":4,"corpo":5,"inteligência":7,"vontade":6,"mente":7,"influência":6,"aura":8,"espírito":7},"temas":[{"nome":"Senhora das Águas","poder":[{"texto":"Hidrocinese Líquida","grau":5},{"texto":"Manipulação de Água em Estado Líquido","grau":4},{"texto":"Pode Purificar ou Contaminar Água","grau":2}],"fraqueza":[]},{"nome":"Temperamento de Maré","poder":[{"texto":"Personalidade Fluida e Serena","grau":3}],"fraqueza":[{"texto":"Agita‑se Sob Pressão","grau":3}]}],"tags":[{"texto":"Hidrocinese Líquida","grau":5},{"texto":"Manipulação de Água em Estado Líquido","grau":4},{"texto":"Personalidade Fluida e Serena","grau":3},{"texto":"Agita‑se Sob Pressão","grau":3},{"texto":"Pode Purificar ou Contaminar Água","grau":2}],"descricao":"Náiade possui um domínio absoluto sobre a água no estado líquido, movendo‑a com a graça de uma correnteza. A sua personalidade reflecte o elemento: calma e adaptável, mas, quando pressionada, torna‑se turbulenta e imprevisível. A sua serenidade é a sua maior força e a sua maior fragilidade."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Náiade' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Mira (Pinpoint)', 'Pinpoint', 'x-men', 'medio', '{"iniciativa":24,"stats":{"destreza":8,"força":3,"corpo":4,"inteligência":9,"vontade":7,"mente":8,"influência":5,"aura":6,"espírito":6},"temas":[{"nome":"Precisão Absoluta","poder":[{"texto":"Localização de Assinaturas Energéticas","grau":5},{"texto":"Identificação de Pontos Fracos","grau":4},{"texto":"Nunca se Perde (Literalmente)","grau":2}],"fraqueza":[]},{"nome":"Mente Metódica","poder":[{"texto":"Mente Analítica e Metódica","grau":4}],"fraqueza":[{"texto":"Arrogância pela Precisão","grau":3}]}],"tags":[{"texto":"Localização de Assinaturas Energéticas","grau":5},{"texto":"Identificação de Pontos Fracos","grau":4},{"texto":"Mente Analítica e Metódica","grau":4},{"texto":"Arrogância pela Precisão","grau":3},{"texto":"Nunca se Perde (Literalmente)","grau":2}],"descricao":"Mira possui um sentido de localização que vai além do geográfico – detecta assinaturas energéticas, pontos de tensão e vulnerabilidades em estruturas e pessoas. Extremamente focada, nunca erra um alvo. A sua precisão beira a arrogância, mas é inegavelmente valiosa em qualquer missão de reconhecimento."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Mira (Pinpoint)' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Trovão', 'Trovão', 'x-men', 'medio', '{"iniciativa":23,"stats":{"destreza":6,"força":5,"corpo":6,"inteligência":5,"vontade":8,"mente":6,"influência":7,"aura":8,"espírito":8},"temas":[{"nome":"Voz de Trovão","poder":[{"texto":"Ondas de Choque Sónicas pela Voz","grau":5},{"texto":"Geração de Trovões e Vibrações","grau":4}],"fraqueza":[]},{"nome":"Alma Incandescente","poder":[{"texto":"Espírito Brasileiro Contagiante","grau":3}],"fraqueza":[{"texto":"Temperamento Explosivo e Caloroso","grau":3},{"texto":"Pode Causar Danos Acústicos Involuntários","grau":2}]}],"tags":[{"texto":"Ondas de Choque Sónicas pela Voz","grau":5},{"texto":"Geração de Trovões e Vibrações","grau":4},{"texto":"Temperamento Explosivo e Caloroso","grau":3},{"texto":"Espírito Brasileiro Contagiante","grau":3},{"texto":"Pode Causar Danos Acústicos Involuntários","grau":2}],"descricao":"Trovão, um brasileiro de alma incandescente, transforma a sua voz numa arma – ondas de choque sônicas capazes de derrubar edifícios. Fala alto, ri alto e sente alto. A sua energia é contagiante, mas o seu temperamento explosivo pode criar problemas. Leva no peito a paixão do futebol e o calor do samba."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Trovão' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Umbra', 'Umbra', 'x-men', 'medio', '{"iniciativa":21,"stats":{"destreza":8,"força":4,"corpo":5,"inteligência":7,"vontade":8,"mente":7,"influência":4,"aura":7,"espírito":7},"temas":[{"nome":"Andarilha das Sombras","poder":[{"texto":"Manipulação e Viagem através das Sombras","grau":5},{"texto":"Furtividade e Infiltração Absolutas","grau":4}],"fraqueza":[]},{"nome":"Guardiã Silenciosa","poder":[{"texto":"Proteção Feroz em Silêncio","grau":3}],"fraqueza":[{"texto":"Introversão e Mistério","grau":3},{"texto":"Depende de Fontes de Sombra","grau":2}]}],"tags":[{"texto":"Manipulação e Viagem através das Sombras","grau":5},{"texto":"Furtividade e Infiltração Absolutas","grau":4},{"texto":"Introversão e Mistério","grau":3},{"texto":"Proteção Feroz em Silêncio","grau":3},{"texto":"Depende de Fontes de Sombra","grau":2}],"descricao":"Umbra é uma figura enigmática que se move e esconde nas sombras, usando‑as tanto para atacar como para se proteger. Prefere a penumbra ao palco, observando mais do que agindo – mas, quando alguém que lhe importa está em perigo, a sua fúria é silenciosa e implacável. Ninguém a vê chegar; apenas sentem o frio."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Umbra' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Xenônio', 'Xenon', 'x-men', 'medio', '{"iniciativa":19,"stats":{"destreza":6,"força":3,"corpo":4,"inteligência":8,"vontade":6,"mente":7,"influência":5,"aura":7,"espírito":6},"temas":[{"nome":"Gás Nobre","poder":[{"texto":"Emissão de Gases e Energias Espectrais","grau":4},{"texto":"Brilho e Inconstância Nobre","grau":4},{"texto":"Pode Criar Ilusões Gasosas","grau":2}],"fraqueza":[]},{"nome":"Inconstância","poder":[],"fraqueza":[{"texto":"Humor Volátil (ora Brilhante, ora Apagado)","grau":3},{"texto":"Dificuldade de se Fixar Física e Mentalmente","grau":3}]}],"tags":[{"texto":"Emissão de Gases e Energias Espectrais","grau":4},{"texto":"Brilho e Inconstância Nobre","grau":4},{"texto":"Humor Volátil (ora Brilhante, ora Apagado)","grau":3},{"texto":"Dificuldade de se Fixar Física e Mentalmente","grau":3},{"texto":"Pode Criar Ilusões Gasosas","grau":2}],"descricao":"Xenônio manipula gases e energias espectrais, projectando luzes e ilusões que desorientam os inimigos. A sua personalidade é tão inconstante como os gases nobres – ora extrovertido e brilhante como néon, ora recolhido e quase invisível. Difícil de prender, seja em batalha ou numa conversa, é um amigo que surge e desaparece sem aviso."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Xenônio' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Anole', 'Anole', 'x-men', 'medio', '{"iniciativa":22,"stats":{"destreza":9,"força":6,"corpo":6,"inteligência":6,"vontade":8,"mente":6,"influência":7,"aura":8,"espírito":8},"temas":[{"nome":"Lagarto Ágil","poder":[{"texto":"Camuflagem e Agilidade Réptil","grau":5},{"texto":"Língua Preênsil e Força Aumentada","grau":4}],"fraqueza":[]},{"nome":"Confiança de Aço","poder":[{"texto":"Sarcasmo e Confiança Inabalável","grau":4},{"texto":"Aberta e Orgulhosamente Gay","grau":3},{"texto":"Coração Maior que a Juba","grau":3}],"fraqueza":[]}],"tags":[{"texto":"Camuflagem e Agilidade Réptil","grau":5},{"texto":"Língua Preênsil e Força Aumentada","grau":4},{"texto":"Sarcasmo e Confiança Inabalável","grau":4},{"texto":"Aberta e Orgulhosamente Gay","grau":3},{"texto":"Coração Maior que a Juba","grau":3}],"descricao":"Anole é um lagarto humanoide cuja pele se adapta ao ambiente e cuja língua pode agarrar oponentes a distância. A sua confiança é tão afiada como as suas garras – não se deixa abater por inseguranças, enfrenta o mundo com sarcasmo e coragem. É o primeiro a rir de si mesmo e o último a abandonar um amigo."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Anole' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
  SELECT gen_random_uuid(), 'Indra', 'Indra', 'x-men', 'medio', '{"iniciativa":18,"stats":{"destreza":5,"força":7,"corpo":8,"inteligência":7,"vontade":9,"mente":7,"influência":6,"aura":7,"espírito":9},"temas":[{"nome":"Escudo Vivo","poder":[{"texto":"Placagens de Armadura Retrácteis","grau":4},{"texto":"Escudos Corporais e Força Defensiva","grau":4}],"fraqueza":[]},{"nome":"Não-Violência","poder":[{"texto":"Pacifismo e Educação Rigorosa","grau":4},{"texto":"Força Interior Inabalável","grau":3}],"fraqueza":[{"texto":"Hesita em Usar Poder Ofensivo","grau":3}]}],"tags":[{"texto":"Placagens de Armadura Retrácteis","grau":4},{"texto":"Escudos Corporais e Força Defensiva","grau":4},{"texto":"Pacifismo e Educação Rigorosa","grau":4},{"texto":"Força Interior Inabalável","grau":3},{"texto":"Hesita em Usar Poder Ofensivo","grau":3}],"descricao":"Indra, oriundo de uma família conservadora indiana, é a gentileza personificada. As suas placas de armadura retrácteis transformam‑no num escudo vivo, mas ele prefere proteger a ferir. A sua força interior é imensa, e a sua hesitação em combate não vem do medo, mas de uma profunda crença na não‑violência."}'::jsonb, TRUE, NOW()
  WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE name = 'Indra' AND is_global = TRUE);
INSERT INTO npcs (id, name, codename, faction, danger, data, is_global, created_at)
